package org.brightstats.report;
import java.util.*;
import org.brightstats.model.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.DiagramGeometry.Point;
/** Standalone vector projection of the typed document; no external images, links or scripts. */
public final class TypedDiagramSvg {
    private TypedDiagramSvg(){}
    public static String render(Document document,String title){var bounds=DiagramGeometry.bounds(document);double width=bounds.width()+80,height=bounds.height()+110,scale=Math.min(1,4000/Math.max(width,height));StringBuilder svg=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"").append((int)Math.ceil(width*scale)).append("\" height=\"").append((int)Math.ceil(height*scale)).append("\" viewBox=\"").append(n(bounds.x()-40)).append(' ').append(n(bounds.y()-70)).append(' ').append(n(width)).append(' ').append(n(height)).append("\"><rect x=\"").append(n(bounds.x()-40)).append("\" y=\"").append(n(bounds.y()-70)).append("\" width=\"").append(n(width)).append("\" height=\"").append(n(height)).append("\" fill=\"white\"/><metadata>").append(xml(document.json().toString())).append("</metadata>");text(svg,bounds.x()-20,bounds.y()-40,title,17,"#173E55");
        for(var link:document.links()){var points=DiagramGeometry.path(document,link);String color=link.type().covariance()?"#7C478F":link.type().modifier()?"#B65C16":"#445B6B";svg.append("<path d=\"M ").append(n(points.getFirst().x())).append(' ').append(n(points.getFirst().y()));if(link.type().covariance())svg.append(" Q ").append(n(points.get(1).x())).append(' ').append(n(points.get(1).y())).append(' ').append(n(points.getLast().x())).append(' ').append(n(points.getLast().y()));else for(int i=1;i<points.size();i++)svg.append(" L ").append(n(points.get(i).x())).append(' ').append(n(points.get(i).y()));svg.append("\" fill=\"none\" stroke=\"").append(color).append("\" stroke-width=\"1.7\"");if(link.type().modifier())svg.append(" stroke-dasharray=\"7 4\"");svg.append("/>");arrow(svg,points.get(points.size()-2),points.getLast(),color);if(link.type().covariance())arrow(svg,points.get(1),points.getFirst(),color);}
        for(var node:document.nodes())if(node.type()!=ElementType.ROOT){var point=DiagramGeometry.position(document,node.id());var size=DiagramGeometry.size(node);String fill=color(node);svg.append("<g><title>").append(xml(node.label()+" · "+node.type())).append("</title>");if(node.type()==ElementType.REGRESSION_INTERCEPT)svg.append("<polygon points=\"").append(n(point.x())).append(',').append(n(point.y()-24)).append(' ').append(n(point.x()+24)).append(',').append(n(point.y()+22)).append(' ').append(n(point.x()-24)).append(',').append(n(point.y()+22)).append("\" fill=\"").append(fill).append("\" stroke=\"#243E50\"/>");else if(size.ellipse())svg.append("<ellipse cx=\"").append(n(point.x())).append("\" cy=\"").append(n(point.y())).append("\" rx=\"").append(n(size.width()/2)).append("\" ry=\"").append(n(size.height()/2)).append("\" fill=\"").append(fill).append("\" stroke=\"#243E50\" stroke-width=\"1.5\"/>");else svg.append("<rect x=\"").append(n(point.x()-size.width()/2)).append("\" y=\"").append(n(point.y()-size.height()/2)).append("\" width=\"").append(n(size.width())).append("\" height=\"").append(n(size.height())).append("\" rx=\"8\" fill=\"").append(fill).append("\" stroke=\"#243E50\" stroke-width=\"1.5\"/>");if(node.type()!=ElementType.DONGLE){String label=node.label().isBlank()?node.type()==ElementType.GAUSSIAN_COPULA?"GC":node.type()==ElementType.CBSEM_ERROR_TERM?"e":"x²":node.label();List<String> lines=lines(label,Math.max(4,(int)(size.width()/7)),3);for(int i=0;i<lines.size();i++){svg.append("<text x=\"").append(n(point.x())).append("\" y=\"").append(n(point.y()+(i-(lines.size()-1)/2.0)*15+4)).append("\" text-anchor=\"middle\" font-family=\"sans-serif\" font-size=\"12\" fill=\"#182D3A\">").append(xml(lines.get(i))).append("</text>");}}svg.append("</g>");}
        for(var note:document.annotations()){var point=DiagramGeometry.annotation(document,note);svg.append("<g><title>").append(xml(note.text())).append("</title><rect x=\"").append(n(point.x())).append("\" y=\"").append(n(point.y())).append("\" width=\"").append(n(note.width())).append("\" height=\"").append(n(note.height())).append("\" fill=\"").append(note.type()==ElementType.POSTIT?"#FFF1B8":"white").append("\" stroke=\"").append(note.type()==ElementType.POSTIT?"#B89A39":"none").append("\"/>");List<String> lines=lines(note.text(),Math.max(4,(int)((note.width()-16)/7)),Math.max(1,(int)((note.height()-12)/16)));for(int i=0;i<lines.size();i++)text(svg,point.x()+8,point.y()+18+16*i,lines.get(i),12,"#182D3A");svg.append("</g>");}return svg.append("</svg>").toString();}
    private static List<String> lines(String value,int width,int maximum){List<String> result=new ArrayList<>();StringBuilder current=new StringBuilder();for(String word:value.replace('\r',' ').split("(?<=\\n)|\\s+")){if(word.isBlank()&&current.length()==0)continue;if(current.length()>0&&current.length()+word.length()+1>width){result.add(current.toString());current.setLength(0);}while(word.length()>width){if(result.size()>=maximum)break;result.add(word.substring(0,width));word=word.substring(width);}if(current.length()>0)current.append(' ');current.append(word);if(word.endsWith("\n")){result.add(current.toString().stripTrailing());current.setLength(0);}if(result.size()>=maximum)break;}if(current.length()>0&&result.size()<maximum)result.add(current.toString());if(result.size()==maximum&&String.join(" ",result).length()<value.length()){String last=result.getLast();result.set(result.size()-1,last.substring(0,Math.min(last.length(),Math.max(1,width-1)))+"…");}return result;}
    private static void text(StringBuilder svg,double x,double y,String text,int size,String color){svg.append("<text x=\"").append(n(x)).append("\" y=\"").append(n(y)).append("\" font-family=\"sans-serif\" font-size=\"").append(size).append("\" fill=\"").append(color).append("\">").append(xml(text)).append("</text>");}
    private static void arrow(StringBuilder svg,Point a,Point b,String color){double angle=Math.atan2(b.y()-a.y(),b.x()-a.x());svg.append("<polygon points=\"").append(n(b.x())).append(',').append(n(b.y())).append(' ').append(n(b.x()-10*Math.cos(angle)+4*Math.sin(angle))).append(',').append(n(b.y()-10*Math.sin(angle)-4*Math.cos(angle))).append(' ').append(n(b.x()-10*Math.cos(angle)-4*Math.sin(angle))).append(',').append(n(b.y()-10*Math.sin(angle)+4*Math.cos(angle))).append("\" fill=\"").append(color).append("\"/>");}
    private static String color(Node node){var properties=node.properties();if(properties.has("color")&&properties.get("color").isJsonPrimitive()&&properties.get("color").getAsJsonPrimitive().isString()){String color=properties.get("color").getAsString();if(color.matches("#[0-9A-Fa-f]{6}"))return color;}if(node.type()==ElementType.GAUSSIAN_COPULA)return "#FFE3C1";if(node.type()==ElementType.QUADRATIC_EFFECT||node.type()==ElementType.PROCESS_MODEL_QUADRATIC_EFFECT)return "#F1D9F4";if(node.type()==ElementType.CBSEM_ERROR_TERM)return "#F0F2F4";if(node.type()==ElementType.DONGLE)return "#B65C16";if(node.type()==ElementType.PROCESS_MODEL_CONTROL_VARIABLE)return "#E3EAD3";return node.type().observed()?"#FFF1B8":"#D8E9F6";}
    private static String n(double value){return Double.toString(value);}
    private static String xml(String value){return XmlText.escape(value);}
}
